mapper.select:

WHERE p.use_yn='Y'
  AND (coalesce(p.prfm_bgn_dt,p.cntrct_bgn_dt) IS NULL
    OR coalesce(p.prfm_bgn_dt,p.cntrct_bgn_dt) < make_date(#{year},12,31)+1)
  AND (coalesce(p.cur_end_dt,p.cntrct_end_dt) IS NULL
    OR coalesce(p.cur_end_dt,p.cntrct_end_dt) >= make_date(#{year},1,1))
AND p.cntrct_ty_cd=#{type}
AND p.bsn_part_id=#{partId}
AND p.prj_stts_cd=#{status}
AND (p.prj_nm ILIKE '%' || #{q} || '%' OR p.prj_no ILIKE '%' || #{q} || '%')
ORDER BY p.prj_id

SELECT p.plan_ym AS month,sum(p.need_mm_qty) AS mm_qty FROM prj.psn_plan p
WHERE p.prj_id=#{id} AND p.plan_ym >= #{from} AND p.plan_ym <= #{through}
GROUP BY p.plan_ym ORDER BY p.plan_ym
